estop.source:
// The leaf of the mill network: six instantiations across three including
// documents, all from this one parsed copy.
chart estop "emergency stop" {
  @doc = "one latching mushroom head",

  state Clear,
  state Tripped,
  state Latched,

  trans * -> Clear,
  trans Clear -> Tripped "pressed",
  trans Tripped -> Latched "held",
  trans Latched -> Clear "twist release",
}

led.source:
// A leaf of the network, included by dock.scav. Deliberately small: what it
// exercises is being the third document, not being an interesting chart.
chart led "status lamp" {
  @doc = "one RGB indicator",

  state Off,
  state Blinking,
  state Solid,

  trans * -> Off,
  trans Off -> Blinking "charging",
  trans Blinking -> Solid "charged",
  trans Solid -> Off "undocked",
}

brew.source:
// Written to touch every element the model holds: nesting, concurrency, every
// pseudostate, and all three attribute spellings. Its dump is a golden.
chart brew "espresso machine" {
  @doc = "counter-top espresso robot",
  @power { mains, watts = "1200" },

  state Off,
  state Standby "warm and idle",
  state SelfCheck choice,

  trans * -> Off,
  trans Off -> SelfCheck "power switch",
  trans SelfCheck -> Standby "ok",
  trans SelfCheck -> Off "fault",

  state Brewing {
    @doc = "both submachines run while a shot pulls",

    submachine water "boiler and pump" {
      state Heating { @tune = "pid" },
      state Pumping,
      trans * -> Heating,
      trans Heating -> Pumping "at temperature",
      trans internal Pumping -> Pumping "pressure adjust",
    },
    submachine grinder {
      state Grinding,
      state Dosing,
      trans * -> Grinding,
      trans Grinding -> Dosing "ground",
    },
  },

  trans Standby -> Brewing "brew button",
  trans Brewing -> Standby "shot done",
  trans Standby -> * "descale overdue",
}

dock.source:
// Included by vac.scav, and includes led.scav itself -- so the network is two
// levels deep and the DocId walk has something to be breadth-first about.
chart dock "charging dock" {
  include "led.scav" as lamp,

  state Empty,
  state On {
    state Seated,
    state Charging,
    trans * -> Seated,
    trans Seated -> Charging "contacts closed",
    // Down into this document's own include, which resolves the same way an
    // ordinary path does once the alias host has its target.
    trans Charging -> lamp/Solid "full",
  },

  trans * -> Empty,
  trans Empty -> On "vacuum docked",
  trans On -> Empty "vacuum left",
}

tcp.source:
// RFC 793 connection states, as a chart rather than as a table.
chart tcp "TCP connection" {
  @doc = "Passive and active opens share the established substate.",

  state Closed,
  state Listen,
  state SynSent,
  state SynReceived,

  trans * -> Closed,
  trans Closed -> Listen "passive open",
  trans Closed -> SynSent "active open",
  trans Listen -> SynReceived "recv SYN",
  trans SynSent -> SynReceived "recv SYN",

  state Established "data may flow both ways" {
    // Both halves close independently, which is why this is concurrent.
    submachine inbound {
      state Open,
      state HalfClosed,
      trans * -> Open,
      trans Open -> HalfClosed "recv FIN",
    },
    submachine outbound {
      state Open,
      state FinSent,
      trans * -> Open,
      trans Open -> FinSent "send FIN", // no more data from us
    },
  },

  trans SynReceived -> Established "recv ACK",
  trans SynSent -> Established "recv SYN+ACK",

  state Closing choice,
  state TimeWait,

  // A transition out of a nested state to a top-level one: the long
  // hierarchical edge the whole project exists for.
  trans Established:inbound/HalfClosed -> Closing,
  trans Established:outbound/FinSent -> Closing,
  trans Closing -> TimeWait "both halves closed",
  trans TimeWait -> Closed "2MSL elapsed",
}

axis.source:
// One servo axis. Instantiated four times: three from mill.scav under the same
// parent submachine, and once more from toolchanger.scav.
chart axis "servo axis" {
  include "estop.scav" as stop,

  state Parked,
  state Homing,
  state Ready,
  state Reached choice,

  // Concurrent: travel runs the profile while monitor watches following error.
  state Moving "under motion" {
    @doc = "both submachines run while the axis travels",

    submachine travel {
      state Accelerating,
      state Cruising,
      state Decelerating,
      trans * -> Accelerating,
      trans Accelerating -> Cruising "at speed",
      trans Cruising -> Decelerating "approaching target",
    },
    submachine monitor "following error watchdog" {
      state Nominal,
      state Excessive,
      trans * -> Nominal,
      trans internal Nominal -> Nominal "sample",
      trans Nominal -> Excessive "error over limit",
    },
  },

  trans * -> Parked,
  trans Parked -> Homing "home",
  trans Homing -> Ready "index found",
  trans Ready -> Moving "move",
  trans Moving -> Reached "target reached",
  trans Reached -> Ready "ok",
  trans Reached -> Parked "out of range",
  // Down into this document's own include.
  trans Moving -> stop/Tripped "limit switch",
}

toolchanger.source:
// A middle document including two others, so `tool/arm/...` from the root
// descends through two include boundaries.
chart toolchanger "carousel tool changer" {
  include "axis.scav" as arm,
  include "estop.scav" as stop,

  state Parked,
  state Rotating,
  state Gripping,
  state Releasing,

  trans * -> Parked,
  trans Parked -> Rotating "select pocket",
  trans Rotating -> Gripping "pocket aligned",
  trans Gripping -> Releasing "tool seated",
  trans Releasing -> Parked "clear",
  // Into the included axis, including one path that needs a submachine
  // qualifier to pick between its two concurrent submachines.
  trans Rotating -> arm/Homing "rehome the arm",
  trans Gripping -> arm/Moving:travel/Cruising "extend",
  trans Releasing -> stop/Clear "reset",
}

bottler.source:
// The deep one. Every other corpus chart nests two or three levels, which is
// where the incumbents look their best; this one runs six and sends faults from
// the innermost valve straight out to the root, so the long-hierarchical edge is
// the point rather than an incidental. Still short of the depth-16 design
// target, which belongs to the generated charts -- a hand-authored one that deep
// is unreadable by construction, which is what the connector hatch is for.
//
// Hand-authored rather than transcribed, and shaped deliberately: the branching
// is uneven at every level, because a chart with uniform fan-out has no
// accidental structure to trip over.
chart bottler "rotary bottling line" {
  @doc = "six nested levels, faults escalating from the valve to the line",
  @machine { heads = "12", rate_bph = "18000" },

  include "estop.scav" as stop,

  state Offline,
  state Draining,
  state Fault,

  state Running "line under production" {
    submachine line {
      state Priming,
      state Idling,

      state Filling "carousel turning" {
        submachine station {
          state Indexing,

          state Docked "bottle clamped" {
            submachine head {
              state Retracted,

              state Engaged "head down on the neck" {
                submachine nozzle {
                  state Sealing,

                  state Dispensing "product flowing" {
                    // The deepest states run concurrently: the valve meters
                    // while the cell integrates weight. Both sit at depth 5.
                    submachine valve {
                      state Metering,
                      state Topping,
                      state Shut,

                      trans * -> Metering,
                      trans Metering -> Topping "coarse volume reached",
                      trans Topping -> Shut "target weight",
                      trans internal Metering -> Metering "flow sample",
                    },
                    submachine cell "load cell integrator" {
                      state Tare,
                      state Weighing,
                      state Settled,

                      trans * -> Tare,
                      trans Tare -> Weighing "first drop",
                      trans Weighing -> Settled "rate below limit",
                      trans internal Weighing -> Weighing "strain sample",
                    },
                  },

                  state Purging,

                  trans * -> Sealing,
                  trans Sealing -> Dispensing "seal confirmed",
                  trans Dispensing -> Purging "shut and clear",
                  trans Purging -> Sealing "line pressure restored",
                },
              },

              trans * -> Retracted,
              trans Retracted -> Engaged "neck located",
              trans Engaged -> Retracted "cycle complete",
            },
          },

          state Releasing,

          trans * -> Indexing,
          trans Indexing -> Docked "bottle present",
          trans Docked -> Releasing "fill complete",
          trans Releasing -> Indexing "clamp open",
        },
      },

      state Capping,

      trans * -> Priming,
      trans Priming -> Idling "pressure nominal",
      trans Idling -> Filling "start command",
      trans Filling -> Capping "bottle filled",
      trans Capping -> Idling "cap torqued",
    },
  },

  trans * -> Offline,
  trans Offline -> Running "enable line",
  trans Running -> Draining "shutdown requested",
  trans Draining -> Offline "circuit empty",

  // The reason this chart exists. Each of these crosses several submachine
  // boundaries, and the deepest leaves the valve at depth 5 for the root.
  trans Running/Filling/Docked/Engaged/Dispensing:valve/Metering -> Fault "overfill detected",
  trans Running/Filling/Docked/Engaged/Dispensing:cell/Weighing -> Fault "load cell open circuit",
  trans Running/Filling/Docked/Engaged/Sealing -> Fault "seal never confirmed",

  // Not every long edge escapes to the root: this one lands three levels up,
  // at the station that owns the head.
  trans Running/Filling/Docked/Engaged/Purging -> Running/Filling/Releasing "abandon this bottle",

  // And back in, which is what makes the ancestor chain pull both ways.
  trans Fault -> Running/Filling/Docked/Retracted "operator cleared",
  trans Fault -> stop/Tripped "latch the estop",
  trans Draining -> Running/Capping "finish the bottle in the capper",
}
